import{z as s,x as r,o as t,c as A,q as i,j as n,D as e,d as m,s as E,S as o,b as p}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Top-a / quadratic sampling","description":"","frontmatter":{"title":"Top-a / quadratic sampling","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/top-a-sampling.md","filePath":"llm/top-a-sampling.md","lastUpdated":1791413859000}'),B={name:"llm/top-a-sampling.md"};function u(d,a,c,_,x,h){const l=r("Mermaid");return t(),A("div",null,[a[2]||(a[2]=i('<h1 id="top-a-quadratic-sampling" tabindex="-1">Top-a / quadratic sampling <a class="header-anchor" href="#top-a-quadratic-sampling" aria-label="Permalink to &quot;Top-a / quadratic sampling&quot;">​</a></h1><div class="epigraph"><p>门槛与当前最大概率的平方成正比时，高峰被切得很狠、平局被放得很开：这是社区里对「相对峰高」截断的一条更陡的曲线，而不是新的训练目标。</p><footer>—— 解码器实现中的 top-$a$ / quadratic 截断；相对峰高的系统研究见 Nguyen 等人的 min-$p$，质量核见 Holtzman nucleus</footer></div><p>Top-\\(a\\) 在本地推理 UI 与若干采样器里作为截断选项出现：下一步只保留满足 \\(p(v)\\ge a\\cdot p_{\\max}^{2}\\) 的 token，再归一化采样。它与 min-\\(p\\) 同属「相对冠军」家族，差别是地板对 \\(p_{\\max}\\) 二次而不是一次。高峰时 \\(p_{\\max}^{2}\\) 仍大，截断极狠，接近只留近义头部；平坦时 \\(p_{\\max}^{2}\\) 迅速变小，门槛塌下去，行为接近几乎不截断。没有一篇与 Holtzman、Meister、Hewitt 同等地位的会议论文把它立为理论对象；本篇按数学对象来写：二次相对地板与一次相对地板、绝对 \\(\\varepsilon\\)、nucleus 质量核之间的几何，以及工程上如何避免空核与和 min-\\(p\\) 重复叠层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Nucleus 的核宽度由累计质量决定，不直接看峰有多尖。绝对 \\(\\varepsilon\\) 看原子大小，不看峰。Min-\\(p\\) 引入 \\(\\tau=p_{\\mathrm{base}}p_{\\max}\\)，让门槛跟置信度走。仍有人觉得一次比例在 \\(p_{\\max}\\) 很高时不够狠：冠军 \\(0.95\\) 时，min-\\(p=0.1\\) 的门槛是 \\(0.095\\)，核里还能塞进不少 \\(0.1\\) 左右的碎项；若希望「非常确信时近乎贪心」，需要门槛随 \\(p_{\\max}\\) 升得更快。平方项提供这条更陡的曲线。反过来，\\(p_{\\max}=0.25\\) 时 \\(p_{\\max}^{2}=0.0625\\)，再乘一个小于 \\(1\\) 的 \\(a\\)，门槛可以低到把大半词表留下，高温创作时不易被截死。</p><p>二次没有信息论推导。它不是典型集，也不控制序列困惑度。把它写进产品，等于选择一条特定的 <em>相对阈值函数</em> \\(g(p_{\\max})=a p_{\\max}^{2}\\)。任何单调的 \\(g\\) 都会给出一种截断器；二次只是其中形状较陡、参数又少的一个。评估应针对形状，而不是针对名字。</p><h3 id="与-min-、-的同一几何族" tabindex="-1">与 min-\\(p\\)、\\(\\varepsilon\\) 的同一几何族 <a class="header-anchor" href="#与-min-、-的同一几何族" aria-label="Permalink to &quot;与 min-$p$、$\\varepsilon$ 的同一几何族&quot;">​</a></h3><p>三类门槛都可以写成 \\(\\tau=g(p_{\\max},H,\\varepsilon)\\)。\\(\\varepsilon\\)：\\(g\\) 为常数。Min-\\(p\\)：\\(g\\) 对 \\(p_{\\max}\\) 线性。Top-\\(a\\)：\\(g\\) 对 \\(p_{\\max}\\) 二次。\\(\\eta\\)：对 \\(\\mathrm{e}^{-H}\\) 自适应，间接与平坦程度有关。画成 \\(\\tau\\)–\\(p_{\\max}\\) 曲线，二次在右端（高置信）高于线性，在左端（低置信）低于线性——若 \\(a\\) 与 \\(p_{\\mathrm{base}}\\) 按某一点对齐的话。不先对齐就比较「谁更狠」没有意义。社区默认 \\(a=0.2\\) 与 \\(p_{\\mathrm{base}}=0.1\\) 不是同一工作点。</p><p><span class="marginnote">名称里的 \\(a\\) 不是 nucleus 的 \\(p\\)，也不是 min-\\(p\\) 的 \\(p_{\\mathrm{base}}\\)。\\(a=0.2\\)、\\(p_{\\max}=0.9\\) 时 \\(\\tau=0.162\\)；同一 \\(a\\)、\\(p_{\\max}=0.4\\) 时 \\(\\tau=0.032\\)。报参数必须同时报公式。</span></p><p><span class="marginnote">数字实例：取 \\(a=0.2\\)。模型很确信、冠军 \\(p_{\\max}=0.95\\) 时，门槛是 \\(0.2\\times 0.95^2\\approx 0.18\\)，概率低于 \\(0.18\\) 的词全部出局，只剩头部两三个近义词；模型犹豫、\\(p_{\\max}=0.25\\) 时，门槛掉到 \\(0.2\\times 0.0625=0.0125\\)，大半词表都留下。同一个旋钮，行为随置信度剧烈换挡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计算 \\(p=\\mathrm{softmax}(z/T)\\)，\\(p_{\\max}=\\max_v p(v)\\)，</p> \\[\\tau = a\\cdot p_{\\max}^{2},\\qquad A=\\{v:p(v)\\ge\\tau\\}. \\]<p>\\(A\\) 为空则回退 \\(\\{\\arg\\max\\}\\)。在 \\(A\\) 上归一化采样。\\(a=0\\) 关闭截断（\\(\\tau=0\\)）。\\(a\\) 过大则即使平坦也切得过狠，失去二次在左端放宽的本意。实现上与 min-\\(p\\) 只差一行乘法；不要同时开两者，最终支撑是更紧的那条门槛，调参无法解释。</p><p>与 nucleus 叠用时同样取交集。若产品已经用 nucleus 处理长尾，再加 top-\\(a\\) 主要在高峰步把核进一步收成近贪心。这可能是想要的（确信时少胡话），应写成「高峰近贪心、平局仍靠 nucleus」，并扫 \\(a\\) 与 \\(\\tau_{\\mathrm{nuc}}\\) 的网格，而不是两个默认值相乘。</p>',15)),(t(),n(o,null,{default:e(()=>[E(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22softmax%20%E5%BE%97%20p%22%5D%20--%3E%20M%5B%22p_max%22%5D%0A%20%20M%20--%3E%20TAU%5B%22%CF%84%20%3D%20a%20%C2%B7%20p_max%C2%B2%22%5D%0A%20%20P%20--%3E%20CMP%5B%22p(v)%20%E2%89%A5%20%CF%84%22%5D%0A%20%20TAU%20--%3E%20CMP%0A%20%20CMP%20--%3E%20A%5B%22%E6%94%AF%E6%92%91%20A%22%5D%0A%20%20A%20--%3E%20N%5B%22%E5%BD%92%E4%B8%80%E5%8C%96%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=p("p",null,[p("span",{class:"marginnote"},"「空核」就是把候选筛成了空集、采样无从下手。对 top-\\(a\\) 这几乎不会由门槛本身造成：冠军概率 \\(m\\) 永远满足 \\(m\\ge a m^{2}\\)（\\(a\\le 1\\) 时恒成立），峰值不会被自己筛掉。真正的空核来自外力——重复惩罚把次优词压到门槛之下，只剩冠军孤零零达标，采样退化成近似贪心。")],-1)),a[4]||(a[4]=p("h2",{id:"机制",tabindex:"-1"},[m("机制 "),p("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=p("p",null,"设冠军概率为 \\(m\\)。线性门槛 \\(c m\\) 与二次门槛 \\(a m^{2}\\) 的比值为 \\((a/c) m\\)。\\(m\\) 靠近 \\(1\\) 时二次相对线性更紧（当 \\(a\\) 与 \\(c\\) 同量级）；\\(m\\) 小于 \\(c/a\\) 时二次更松。于是同一套「相对峰高」叙事下，二次把动态范围拉得更开：自信时更像贪心，犹豫时更像温度采样。这与人在写作时的直觉接近——想词时很宽，词已经到嘴边时很窄——但 LM 的 \\(m\\) 未必等于「词到嘴边」：校准差的模型会在胡话前仍然给出很高的 \\(m\\)，二次会把胡话核收成一个高自信错误。校准越好，二次越像在执行该直觉。",-1)),(t(),n(o,null,{default:e(()=>[E(l,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%86%A0%E5%86%9B%E6%A6%82%E7%8E%87%20m%20%E7%9A%84%E5%A4%A7%E5%B0%8F%22%5D%20--%3E%20Q%7B%22%E6%A8%A1%E5%9E%8B%E6%AD%A4%E5%88%BB%E8%87%AA%E4%BF%A1%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22m%20%E9%9D%A0%E8%BF%91%201%EF%BC%9A%E8%87%AA%E4%BF%A1%22%7C%20HI%5B%22%E4%BA%8C%E6%AC%A1%E9%97%A8%E6%A7%9B%E5%8D%87%E5%BE%97%E6%AF%94%E7%BA%BF%E6%80%A7%E5%BF%AB%EF%BC%8C%E6%A0%B8%E6%94%B6%E7%AA%84%E8%BF%91%E8%B4%AA%E5%BF%83%22%5D%0A%20%20Q%20--%3E%7C%22m%20%E5%BE%88%E5%B0%8F%EF%BC%9A%E7%8A%B9%E8%B1%AB%22%7C%20LO%5B%22%E4%BA%8C%E6%AC%A1%E9%97%A8%E6%A7%9B%E5%A1%8C%E4%B8%8B%E5%8E%BB%EF%BC%8C%E6%A0%B8%E6%94%BE%E5%AE%BD%E8%BF%91%E4%BC%BC%E6%B8%A9%E5%BA%A6%E9%87%87%E6%A0%B7%22%5D%0A%20%20HI%20--%3E%20R1%5B%22%E9%A3%8E%E9%99%A9%EF%BC%9A%E6%A8%A1%E5%9E%8B%E6%A0%A1%E5%87%86%E5%B7%AE%E6%97%B6%EF%BC%8C%E9%AB%98%E8%87%AA%E4%BF%A1%E9%94%99%E8%AF%AF%E8%A2%AB%E9%94%81%E6%AD%BB%22%5D%0A%20%20LO%20--%3E%20R2%5B%22%E6%94%B6%E7%9B%8A%EF%BC%9A%E7%9C%9F%E5%B9%B3%E5%B1%80%E9%87%8C%E5%A4%9A%E4%B8%AA%E8%BF%91%E4%B9%89%E5%80%99%E9%80%89%E9%83%BD%E8%A2%AB%E4%BF%9D%E7%95%99%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[m(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h3 id="高峰误信与平局真不确定" tabindex="-1">高峰误信与平局真不确定 <a class="header-anchor" href="#高峰误信与平局真不确定" aria-label="Permalink to &quot;高峰误信与平局真不确定&quot;">​</a></h3><p>二次放大了 \\(m\\) 作为置信度代理的权重。若模型在实体名上过度自信，\\(a p_{\\max}^{2}\\) 会删掉正确的次优实体。Min-\\(p\\) 同有此问题，二次更重。若模型在标点与功能词上 \\(m\\) 很高，二次几乎锁死标点选择，对散文影响小，对需要罕见标点的格式可能有影响。平坦的真不确定（多个近义动词）是二次想保护的区域：门槛塌下，nucleus 或温度仍能在其中选。把 top-\\(a\\) 当「万能创意旋钮」会在校准差的模型上得到更武断的错误，而不是更丰富的正确续写。</p><p>数值上 \\(m^{2}\\) 在半精度里通常无问题，\\(m\\) 不会小到下溢后再平方才出事；真正的空核来自 \\(a\\) 大且 \\(m\\) 中等、同时叠了重复惩罚把次优项压到 \\(\\tau\\) 以下。回退规则与 <a href="/llm/epsilon-sampling">\\(\\varepsilon\\)-sampling</a> 相同。</p><p><span class="marginnote">Top-\\(k\\) 的 \\(k\\) 是基数约束，top-\\(a\\) 的 \\(a\\) 是相对二次地板。名字里都有 top，集合构造毫无关系。不要把 \\(a\\) 理解成「再留百分之 \\(a\\) 的词表」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="与-typical、min-选一条曲线即可" tabindex="-1">与 typical、min-\\(p\\) 选一条曲线即可 <a class="header-anchor" href="#与-typical、min-选一条曲线即可" aria-label="Permalink to &quot;与 typical、min-$p$ 选一条曲线即可&quot;">​</a></h3><p>没有权威论文表格可抄，\\(a\\) 必须在目标模型与温度上自扫。与 Meister 的局部典型相比，二次 <em>保留峰值</em>（只要峰值高于 \\(\\tau\\)，而峰值总是 \\(\\ge\\tau\\) 当 \\(a\\le 1/m\\) 即 \\(a\\le 1\\) 量级时恒成立：\\(m\\ge a m^{2}\\iff 1\\ge a m\\)，因 \\(m\\le 1\\)、\\(a\\le 1\\) 时常真）。典型集可能丢掉峰值；top-\\(a\\) 不会。若目标是少套话，二次帮不上忙，应用 typical 或对比搜索。若目标是高温下仍连贯，二次与 min-\\(p\\) 同一赛道，应直接对照两者的 \\(\\tau\\)–\\(m\\) 曲线再选一条，不要两条一起开。</p><p>投机无损要求草稿用同一 \\(a\\) 与同一 \\(T\\) 构造 \\(A\\)。CFG 在混合 logits 之后再算 \\(p_{\\max}\\)。服务默认值应在文档里写出公式字符串 <code>a * p_max**2</code>，避免调用方按 nucleus 的语义传入 \\(0.9\\)。评测开放生成时把 \\(T\\)、\\(a\\)、是否另有 nucleus 写成协议；只写「开了 top-a」无法复现。</p><p><span class="marginnote">为什么这一条重要：同一份「top-\\(a=0.2\\)」配置，在不同采样器里可能按不同公式实现，产出完全不同的文本。复现实验或对齐线上行为时，第一个要核对的就是门槛公式和温度是否逐字一致，而不是参数名字面相同。</span></p><p>不要把二次门槛推广成「再乘一次 \\(p_{\\max}\\) 一定更好」。三次会在中等 \\(m\\) 上过早塌到数值噪声以下，等于低温时近贪心、中温时突然全开，中间没有可用区。二次已经够陡。更有原则的自适应应看熵（\\(\\eta\\)、typical、Mirostat），而不是继续加 \\(p_{\\max}\\) 的幂。</p><p><span class="marginnote">出处以采样器实现与相对峰高截断的几何为准。系统实验与高温叙事对照 Nguyen et al. 的 min-\\(p\\)（2024）；质量核对照 Holtzman et al., ICLR 2020。不要给 top-\\(a\\) 编造会议论文页码。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Top-\\(a\\) 保留 \\(p(v)\\ge a p_{\\max}^{2}\\) 的 token，是相对冠军的二次地板，不是质量核，也不是典型集。</li><li>相对 min-\\(p\\) 的线性地板，二次在高 \\(p_{\\max}\\) 更紧、在低 \\(p_{\\max}\\) 更松，动态范围更大。</li><li>它放大「用 \\(p_{\\max}\\) 当置信度」的假设；校准差时会把高自信错误切成近贪心。</li><li>与 nucleus、min-\\(p\\)、\\(\\varepsilon\\) 同属逐步截断，不要无声明取交集。</li><li>峰值始终可进支撑（常见 \\(a\\) 下），故不能靠它去套话；少套话应看 typical 或对比搜索。</li><li>参数 \\(a\\) 必须与温度联合扫描，并在 API 文档里写出公式。</li><li>出处：解码器中的 top-\\(a\\) 规则；相对峰高截断的对照见 Nguyen et al., <em>Min-P Sampling</em>, 2024；nucleus 见 Holtzman et al., ICLR 2020。</li></ul>',13))])}const f=s(B,[["render",u]]);export{C as __pageData,f as default};
